UPDATE assessment_template_versions tv
SET schema_definition = $schema${"instrument_number":5,"template_name":"Commercial Performance & Growth Assessment","description":"An advisor-led assessment of market position, customer economics, demand generation, sales conversion, pricing, retention and expansion. Commercial conclusions distinguish historical results, owner-reported information, verified evidence and advisor hypotheses.","schema_status":"active","sections":[{"id":"market_position","title":"1. Market, positioning & competitive context","description":"Understand who the business serves, why customers choose it and how its position is supported by evidence.","questions":[{"key":"com_market_segments","label":"Primary customer segments and target markets","type":"textarea","required":true,"prompt":"Define customer types, industries, geographies, use cases and meaningful segment differences. Avoid unsupported market-size estimates."},{"key":"com_ideal_customer","label":"Ideal customer profile and buying characteristics","type":"textarea","required":true,"prompt":"Describe best-fit customers, needs, buying triggers, decision-makers, budget characteristics and disqualifiers."},{"key":"com_value_proposition","label":"Core value proposition and customer outcomes","type":"textarea","required":true,"prompt":"What problem does the business solve, what outcome does the customer receive, and how is that outcome demonstrated?"},{"key":"com_differentiation","label":"Differentiation and reasons customers choose the business","type":"textarea","prompt":"Capture customer-stated reasons, win/loss evidence, service advantages, capabilities, price, convenience and reputation."},{"key":"com_competitors","label":"Competitors, substitutes and alternative solutions","type":"textarea","required":true,"prompt":"Include direct competitors, internal customer alternatives, doing nothing and substitute approaches. Identify evidence sources."},{"key":"com_market_evidence","label":"Market and competitive evidence reviewed","type":"textarea","prompt":"Record customer interviews, win/loss notes, market research, public pricing, industry data and evidence dates. Separate sourced facts from assumptions."}]},{"id":"customer_portfolio","title":"2. Customer portfolio & revenue quality","description":"Evaluate customer mix, concentration, repeat behavior and the quality and economics of revenue.","questions":[{"key":"com_customer_count","label":"Active customers in the assessment period","type":"number","unit":"customers","prompt":"Define active customer and reporting period; leave blank if not reliably measured."},{"key":"com_customer_concentration","label":"Revenue concentration by largest customers","type":"textarea","required":true,"prompt":"Where available, record top 1, top 5 and top 10 customer revenue shares, period, calculation basis and source. Do not estimate if unknown."},{"key":"com_revenue_mix","label":"Revenue mix by product, service, segment or channel","type":"textarea","required":true,"prompt":"Break down revenue using consistent categories and a defined historical period. Distinguish recurring, repeat, contracted and one-time project revenue."},{"key":"com_recurring_share","label":"Recurring / contracted revenue share (%)","type":"number","unit":"percent","prompt":"Only enter if recurring revenue is clearly defined and the period and denominator are known."},{"key":"com_repeat_rate","label":"Repeat purchase / returning customer rate (%)","type":"number","unit":"percent","prompt":"Define cohort, period, numerator and denominator. Leave blank if not measured."},{"key":"com_retention_churn","label":"Customer retention, churn and cohort trends","type":"textarea","prompt":"Describe gross retention, logo churn, revenue churn or repeat behavior where measured. State definitions, period and source."},{"key":"com_deal_value","label":"Average deal / transaction value and trend","type":"textarea","prompt":"Record value, currency, period, sample size and segment. Note whether mean, median or another measure is used."},{"key":"com_customer_economics","label":"Gross margin or contribution by customer / offering","type":"textarea","prompt":"Identify profitable and unprofitable segments where supported. State allocation assumptions and data limitations."}]},{"id":"demand_generation","title":"3. Lead generation & demand creation","description":"Assess how prospects discover the business and how effectively channels create qualified demand.","questions":[{"key":"com_channel_mix","label":"Lead generation channels and current activity","type":"textarea","required":true,"prompt":"Include referrals, organic search, paid media, social, outbound, partners, marketplaces, events and repeat business."},{"key":"com_lead_volume","label":"Lead and qualified-lead volume by period","type":"textarea","prompt":"Record counts by channel and period, with definitions of lead and qualified lead. Include source and attribution limitations."},{"key":"com_channel_conversion","label":"Channel-level lead quality and conversion","type":"textarea","prompt":"Compare qualified lead rate, opportunity creation, wins and revenue by channel where reliable."},{"key":"com_marketing_spend","label":"Marketing and demand-generation spend","type":"textarea","prompt":"Record spend by channel and period, including agency, platform, labor and campaign costs when available."},{"key":"com_acquisition_cost","label":"Customer acquisition cost (CAC), if supportable","type":"textarea","prompt":"Only calculate where acquisition spend and attributable new customers are defined for the same period and scope. State inclusions, exclusions and limitations; otherwise explain why unavailable."},{"key":"com_attribution","label":"Lead attribution, tracking and reporting capability","type":"select","required":true,"options":["Reliable source tracking through revenue","Partial tracking with known gaps","Activity tracked but revenue attribution weak","Mostly anecdotal / manual tracking","Not yet assessed"]},{"key":"com_demand_constraints","label":"Demand-generation constraints and opportunities","type":"textarea","prompt":"Identify channel saturation, inconsistent activity, weak positioning, limited content, budget, capacity or measurement issues."}]},{"id":"sales_conversion","title":"4. Sales process & conversion","description":"Review the path from inquiry to closed business, including pipeline quality, sales execution and forecasting.","questions":[{"key":"com_sales_process","label":"Sales stages, ownership and handoffs","type":"textarea","required":true,"prompt":"Map inquiry through qualification, discovery, proposal, negotiation, close and handoff. Identify owners and exit criteria."},{"key":"com_pipeline_volume","label":"Current pipeline volume and value","type":"textarea","prompt":"State date, currency, stage definitions, gross versus weighted value and source. Separate qualified pipeline from unqualified leads."},{"key":"com_win_rate","label":"Win rate / close rate (%)","type":"number","unit":"percent","prompt":"Define wins divided by which set of opportunities, period and treatment of open/lost deals."},{"key":"com_sales_cycle","label":"Typical sales cycle length","type":"text","prompt":"Specify unit, start/end events, period, segment and whether this is mean or median."},{"key":"com_pipeline_coverage","label":"Pipeline coverage against sales target","type":"textarea","prompt":"If used, state qualified pipeline divided by target, period, stage weighting and assumptions."},{"key":"com_forecast_accuracy","label":"Sales forecast accuracy and operating cadence","type":"textarea","prompt":"Compare prior forecasts with actual outcomes where available. Describe review cadence, ownership and confidence."},{"key":"com_loss_reasons","label":"Lost-deal reasons, stalled opportunities and sales friction","type":"textarea","prompt":"Use CRM or interview evidence where possible. Separate recorded loss reasons from inferred explanations."},{"key":"com_sales_capability","label":"Sales capacity, skills and process consistency","type":"textarea","prompt":"Assess coverage, productivity, onboarding, incentives, tools, follow-up discipline and owner dependency."}]},{"id":"pricing_retention","title":"5. Pricing, offers, retention & expansion","description":"Evaluate monetization, price realization, customer experience and growth within the existing customer base.","questions":[{"key":"com_pricing_model","label":"Pricing structure and commercial terms","type":"textarea","required":true,"prompt":"Describe packages, rate cards, subscriptions, retainers, usage pricing, project fees, contract length and renewal terms."},{"key":"com_discounting","label":"Discounting, concessions and price realization","type":"textarea","prompt":"Capture discount frequency, approval controls, free work, payment terms and difference between list and realized price."},{"key":"com_offer_performance","label":"Performance of products, services and offers","type":"textarea","prompt":"Compare revenue, volume, margin, conversion and customer fit by offer where data permits."},{"key":"com_pricing_power","label":"Customer price sensitivity and pricing power","type":"textarea","prompt":"Use documented tests, customer feedback, lost deals and renewal outcomes. Mark untested pricing ideas as hypotheses."},{"key":"com_expansion","label":"Upsell, cross-sell and account expansion","type":"textarea","prompt":"Describe expansion revenue, attach rates, account plans, triggers, ownership and measured results."},{"key":"com_retention_program","label":"Customer onboarding, service, retention and renewal practices","type":"textarea","prompt":"Assess onboarding, customer success, support, renewal reminders, feedback loops and escalation."},{"key":"com_churn_reasons","label":"Customer attrition and reasons for leaving","type":"textarea","prompt":"Record known reasons, customer feedback, preventability, timing and revenue impact. Distinguish confirmed reasons from assumptions."},{"key":"com_commercial_risks","label":"Commercial risks and growth constraints","type":"textarea","required":true,"prompt":"Consider concentration, channel dependence, margin erosion, capacity, reputation, contract terms, competition and customer experience."}]},{"id":"advisor_diagnosis","title":"6. Advisor findings, growth opportunities & commercial risks","description":"Synthesize the evidence into commercial findings and testable growth opportunities.","questions":[{"key":"com_strengths","label":"Commercial strengths and advantages to preserve","type":"textarea","required":true,"prompt":"Identify customer relationships, channels, offers, capabilities and reputation that demonstrably create value."},{"key":"com_findings","label":"Key advisor findings","type":"textarea","required":true,"prompt":"Separate verified historical results, source records, owner-reported information, customer statements and advisor interpretation."},{"key":"com_root_causes","label":"Root causes and hypotheses requiring validation","type":"textarea","prompt":"Identify underlying causes of weak demand, low conversion, churn, low margin or limited expansion. Mark hypotheses clearly."},{"key":"com_growth_opportunities","label":"Prioritized commercial growth opportunities","type":"textarea","required":true,"prompt":"Describe target segment, commercial mechanism, expected leading indicators, evidence needed, effort, dependencies and risks. Do not invent revenue impact."},{"key":"com_customer_impact","label":"Customer experience and brand implications","type":"textarea","prompt":"Consider customer trust, service quality, delivery capacity, employee impact and potential brand consequences."},{"key":"com_evidence_gaps","label":"Evidence gaps and next validation steps","type":"textarea","prompt":"List missing CRM, transaction, marketing, customer, margin or competitor evidence and how it should be obtained."},{"key":"com_advisor_confidence","label":"Advisor confidence in this assessment","type":"select","required":true,"options":["High — sufficient direct evidence and corroboration","Moderate — useful findings with material gaps","Low — preliminary hypotheses / limited access","Insufficient — defer conclusions pending evidence"]}]}],"assessment_policy":"Use historical results only when reporting period, definitions, scope and source are stated. Owner-reported figures are not independently verified. Do not calculate CAC, conversion, retention, pipeline coverage or market size without valid numerator, denominator, period and scope. Forecasts and advisor hypotheses must be labeled separately from actual results. Missing data is unknown, not zero or poor performance."}$schema$::jsonb,
    scoring_definition = '{"rating_owner":"advisor","missing_data_policy":"Unknown or unmeasured is not zero or poor performance.","evidence_policy":"Separate historical records, owner-reported data, customer statements, verified evidence and advisor hypotheses.","metric_policy":"Commercial metrics require clear definitions, periods, scope and denominators. Do not calculate CAC or conversion rates from incomplete inputs."}'::jsonb,
    published_at = COALESCE(tv.published_at, now())
FROM assessment_templates t
WHERE tv.template_id=t.id
  AND t.instrument_number=5
  AND tv.version_number=t.current_version;